#include <iostream>
#include <vector>
#include <algorithm>

using namespace std::cout;

int main() {
    // Create the 1x1 rectangle
    int width = 10;
    int height = 10;
    std::vector<int> rectangle(width, 0);
    std::vector<int> grid(rectangle.size());

    // Fill the rectangle with the shaded portions
    for (int j = 0; j < 4; ++j) {
        rectangle[j] = (rectangle[j] + width - 1) / width;
    }
    for (int j = 0; j < 5; ++j) {
        rectangle[j] = (rectangle[j] + height - 1) / height;
    }

    // Create the grid
    std::cout << "Grid:" << std::endl;
    for (int i = 0; i < rectangle.size(); ++i) {
        std::cout << rectangle[i] << " ";
    }
    std::cout << "\n";

    // Draw the rectangle and its shaded portions
    for (int i = 0; i < rectangle.size(); ++i) {
        std::cout << "  " << rectangle[i] << " " << grid[i] << std::endl;
    }

    // Calculate the area of the shaded region
    int area = rectangle.size() - 1;
    std::cout << "Area of shaded region: " << area << " pixels" << std::endl;

    return 0;
}
```

